import { createHash, timingSafeEqual } from "node:crypto";
import { getConfig } from "#/config/server.ts";

/**
 * One-time setup token (SETUP_TOKEN, generated by the installer and
 * printed once): while no account exists, the first sign-up and the
 * first-run restore need it, so whoever reaches a fresh panel first cannot
 * take it over. It means nothing once an account exists (both paths are
 * closed then). Unset (development, manual installs): the old behaviour,
 * with a warning on the sign-up page.
 */
export function setupTokenRequired(): boolean {
	return !!getConfig().SETUP_TOKEN;
}

const digest = (value: string) => createHash("sha256").update(value).digest();

/** Constant-time comparison (both sides hashed: equal lengths). */
export function setupTokenMatches(given: string | null | undefined): boolean {
	const expected = getConfig().SETUP_TOKEN;
	if (!expected) return true;
	if (typeof given !== "string" || given.length === 0) return false;
	return timingSafeEqual(digest(given.trim()), digest(expected));
}
